import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const BaoCaoThongKe = () => {
    const [selectedTab, setSelectedTab] = useState('finance');
    const [loading, setLoading] = useState(false);

    // ĐẦU CHỜ BACKEND: Mặc định là null (Trống hoàn toàn)
    const [reportData, setReportData] = useState(null);

    const reportTabs = [
        { id: 'finance', name: 'Tài chính', icon: '💰' },
        { id: 'vehicle', name: 'Phương tiện', icon: '🚗' },
        { id: 'maintenance', name: 'Bảo trì', icon: '🛠️' },
        { id: 'resident', name: 'Cư dân', icon: '👥' }
    ];

    // --- LOGIC KẾT NỐI BACKEND ---
    useEffect(() => {
        const fetchStatistics = async () => {
            setLoading(true);
            try {
                // Khi chưa có Backend, chúng ta set về một object trống chuẩn cấu trúc
                // Để giao diện không bị lỗi crash nhưng vẫn hiển thị là "Trống"
                setReportData({
                    title: reportTabs.find(t => t.id === selectedTab).name.toUpperCase(),
                    cards: [], // Không có thẻ số liệu nào
                    hasData: false
                });

                /* SAU NÀY CÓ BACKEND:
                const res = await axios.get(`/api/admin/stats?type=${selectedTab}`);
                setReportData({...res.data, hasData: true});
                */
            } catch (error) {
                console.error("Lỗi truy xuất hệ thống:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchStatistics();
    }, [selectedTab]);

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>📊 HỆ THỐNG BÁO CÁO ADMIN</h2>
            </div>

            <div style={contentWrapperStyle}>

                {/* CỘT TRÁI: DANH MỤC CHỨC NĂNG */}
                <div style={sidebarStyle}>
                    {reportTabs.map(tab => (
                        <div key={tab.id} onClick={() => setSelectedTab(tab.id)}
                            style={{ 
                                ...tabItemStyle,
                                background: selectedTab === tab.id ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: selectedTab === tab.id ? '#fff' : '#333',
                            }}>
                            <span style={{ fontSize: '24px' }}>{tab.icon}</span>
                            <span style={{ fontSize: '14px', fontWeight: 'bold' }}>{tab.name}</span>
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: HIỂN THỊ DỮ LIỆU TRỐNG (CHỜ BACKEND) */}
                <div style={mainContentStyle}>
                    {loading ? (
                        <div style={centerTextStyle}>ĐANG TRUY XUẤT HỆ THỐNG...</div>
                    ) : reportData ? (
                        <div style={{ animation: 'fadeIn 0.3s', height: '100%', display: 'flex', flexDirection: 'column' }}>

                            <div style={titleHeaderStyle}>
                                <span style={subTitleStyle}>BÁO CÁO TỔNG HỢP</span>
                                <h1 style={mainTitleStyle}>{reportData.title}</h1>
                            </div>

                            {/* Hiển thị nếu có dữ liệu */}
                            {reportData.hasData && reportData.cards.length > 0 ? (
                                <div style={statsGridStyle}>
                                    {reportData.cards.map((card, index) => (
                                        <div key={index} style={cardContainerStyle}>
                                            <span style={cardLabelStyle}>{card.label}</span>
                                            <div style={cardValueWrapper}>
                                                <span style={cardValueStyle}>{card.value}</span>
                                                <span style={cardUnitStyle}>{card.unit}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                // HIỂN THỊ KHI TRANG TRỐNG
                                <div style={emptyDataBox}>
                                    <div style={{ fontSize: '60px', marginBottom: '20px' }}>📉</div>
                                    <h3 style={{ color: '#555' }}>CHƯA CÓ DỮ LIỆU THỐNG KÊ</h3>
                                    <p style={{ color: '#999', maxWidth: '400px' }}>
                                        Hệ thống chưa tìm thấy dữ liệu liên kết từ mục <strong>{reportData.title}</strong>. 
                                        Vui lòng cập nhật thông tin cư dân và hóa đơn để xem báo cáo.
                                    </p>
                                </div>
                            )}

                            {/* Khung chờ biểu đồ */}
                            <div style={chartPlaceholderStyle}>
                                <p style={{ color: '#ccc' }}>Biểu đồ sẽ tự động dựng khi có dữ liệu từ Database</p>
                            </div>

                        </div>
                    ) : null}
                </div>
            </div>

            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

// --- STYLES ĐỒNG BỘ ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)' };
const headerStyle = { padding: '20px', background: 'rgba(0,0,0,0.2)' };
const contentWrapperStyle = { flex: 1, padding: '25px', display: 'flex', gap: '25px', overflow: 'hidden' };
const sidebarStyle = { width: '180px', display: 'flex', flexDirection: 'column', gap: '15px' };
const tabItemStyle = { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100px', borderRadius: '20px', cursor: 'pointer', transition: '0.3s' };
const mainContentStyle = { flex: 1, backgroundColor: 'rgba(255,255,255,0.95)', borderRadius: '30px', padding: '40px', display: 'flex', flexDirection: 'column' };
const titleHeaderStyle = { borderBottom: '3px solid #8b5e5e', paddingBottom: '20px', marginBottom: '30px' };
const subTitleStyle = { fontSize: '14px', color: '#8b5e5e', fontWeight: 'bold' };
const mainTitleStyle = { fontSize: '40px', margin: 0, fontWeight: '900', color: '#333' };
const statsGridStyle = { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' };
const cardContainerStyle = { background: '#fff', padding: '25px', borderRadius: '25px', boxShadow: '0 10px 30px rgba(0,0,0,0.05)', border: '1px solid #f0f0f0', textAlign: 'center' };
const cardLabelStyle = { color: '#888', fontSize: '14px' };
const cardValueWrapper = { display: 'flex', alignItems: 'baseline', justifyContent: 'center', gap: '5px' };
const cardValueStyle = { fontSize: '36px', fontWeight: '900', color: '#8b5e5e' };
const cardUnitStyle = { fontSize: '16px', color: '#aaa' };
const chartPlaceholderStyle = { height: '150px', background: '#fcfcfc', borderRadius: '25px', border: '2px dashed #eee', display: 'flex', alignItems: 'center', justifyContent: 'center', marginTop: 'auto' };
const centerTextStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#fff', fontSize: '18px' };
const emptyDataBox = { flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center' };

export default BaoCaoThongKe;
